(function() {
    // 1. Raw Dataset from 25中排灣語_句型練習.pdf (250 A-B Dialogues)
    window.PAIWAN_RAW_DATASET = [{"id": 1, "page": 1, "section": "情境族語", "a_pw": "pulingalingav sun tua ’u sinitulu?", "a_zh": "你聽得懂我教的嗎", "b_pw": "ini a’en a mapulingalingav anan, maqati sun a mumalj a temulu, sinsi?", "b_zh": "我還聽不懂，可以請老師您再教一次嗎？"}, {"id": 2, "page": 1, "section": "情境族語", "a_pw": "sinsi, ini a’en a paqenetj anga a ’emacu tua ’u ’inpic.", "a_zh": "老師，我忘了帶筆。", "b_pw": "u pasedjamai sun.", "b_zh": "我借你。"}, {"id": 3, "page": 1, "section": "情境族語", "a_pw": "pai alapu a nu siquliqulip.", "a_zh": "來把你們的橡皮擦取走。", "b_pw": "sinsi, ini a’en a paqenetj anga a ’emacu tua ’u siquliqulip.", "b_zh": "老師，我忘了帶橡皮擦。"}, {"id": 4, "page": 1, "section": "情境族語", "a_pw": "tima sun?", "a_zh": "你是誰？", "b_pw": "ti ljavuras a’en.", "b_zh": "我是ljavuras。"}, {"id": 5, "page": 1, "section": "情境族語", "a_pw": "tima su ngadaan?", "a_zh": "你叫什麼名字？", "b_pw": "ti Qadeves a ’u ngadaan", "b_zh": "我的名字叫Qedeves。"}, {"id": 6, "page": 2, "section": "情境族語", "a_pw": "tima ngadaan ni tjama?", "a_zh": "你爸爸叫什麼名字？", "b_pw": "ti Sedjam a ngadaan ni ama.", "b_zh": "我爸爸的名字是Sedjam。"}, {"id": 7, "page": 2, "section": "情境族語", "a_pw": "tima zua?", "a_zh": "他是誰？", "b_pw": "ti Bua.", "b_zh": "他是Bua。"}, {"id": 8, "page": 2, "section": "情境族語", "a_pw": "ti Gese a ngadaan nimadju?", "a_zh": "他的名字是Gese嗎？", "b_pw": "ui, pina’a ti Gese timadju.", "b_zh": "是，他被稱為Gese。"}, {"id": 9, "page": 2, "section": "情境族語", "a_pw": "ti Gese a ngadaan nimadju?", "a_zh": "他的名字是Gese嗎？", "b_pw": "ini, ti Apang a ngadaan nimadju.", "b_zh": "不是，他的名字叫Apang"}, {"id": 10, "page": 2, "section": "情境族語", "a_pw": "tima zua?", "a_zh": "那個人是誰？", "b_pw": "ti ’ina i Aljuy, a siruvetje’ ni ’ina.", "b_zh": "他是Aljuy阿姨，我媽的姊妹"}, {"id": 11, "page": 2, "section": "情境族語", "a_pw": "mapida a su siruvetje’?", "a_zh": "你有幾個兄弟姊妹？", "b_pw": "aza ’u siruvetje’ a vavayan, izua macidilj a tjavulung tjanua’an, sa macidilj a tjaljalja’.", "b_zh": "我有一個姊姊和一個妹妹。"}, {"id": 12, "page": 3, "section": "情境族語", "a_pw": "izua su siruvetje’ a tjavulung tjanusun a uqaljay?", "a_zh": "你有哥哥嗎？", "b_pw": "ne’a nu tjavulung tjanua’en a uqaljay ta ’u siruvetje’.", "b_zh": "我沒有哥哥。"}, {"id": 13, "page": 3, "section": "情境族語", "a_pw": "ma(lje)pida mun a tace’eljan?", "a_zh": "你們家有幾個人？", "b_pw": "masepatj amen a tace’eljan.", "b_zh": "我們家有4個人。"}, {"id": 14, "page": 3, "section": "情境族語", "a_pw": "i zainu sun a ’itulutulu?", "a_zh": "你在哪裡讀書？", "b_pw": "i Taihuku a’en a ’itulutulu.", "b_zh": "我在台北讀書。"}, {"id": 15, "page": 3, "section": "情境族語", "a_pw": "anema a sengesengan na siruvetje’ ni tja’ina a uqalay?", "a_zh": "你的舅舅從事什麼工作？", "b_pw": "kisacu timadju", "b_zh": "他是警察。"}, {"id": 16, "page": 3, "section": "情境族語", "a_pw": "izua sengesengan na su vetje’ a vavayan a tjavulung?", "a_zh": "你的姊姊有工作嗎？", "b_pw": "izua i biyuing a ’ipusengesengesengan.", "b_zh": "她在醫院上班。"}, {"id": 17, "page": 3, "section": "情境族語", "a_pw": "paiwan mun?", "a_zh": "你們是原住民嗎？", "b_pw": "ui, paiwan amen.", "b_zh": "是的，我們是原住民。"}, {"id": 18, "page": 4, "section": "情境族語", "a_pw": "qacaqaca ti tjama?", "a_zh": "你的爸爸很高嗎？", "b_pw": "ui, qaqacaqacaan amen a masanetalj a tace’eljan.", "b_zh": "對，我們全家都很高。"}, {"id": 19, "page": 4, "section": "情境族語", "a_pw": "a magakuku anga su vetje’ a za tjaljalja’ tjanusun a vavayan?", "a_zh": "你的妹妹上學了嗎？", "b_pw": "ui, magakuku anga timadju.", "b_zh": "是，她上學了。"}, {"id": 20, "page": 4, "section": "情境族語", "a_pw": "nama’uda a qiljas tucu?", "a_zh": "今晚天氣如何？", "b_pw": "ne’a za qiljas sa ne’a za qerepus, mapacucun a vitjuqan.", "b_zh": "沒月也無雲，看得到星星。"}, {"id": 21, "page": 4, "section": "情境族語", "a_pw": "nama’uda a qadav tatiav?", "a_zh": "昨天天氣如何？", "b_pw": "tjaumeljay, sa tjevuta anga a qadav, sa izua za quljivangrav.", "b_zh": "雨剛剛停，出了太陽，彩虹出來了。"}, {"id": 22, "page": 4, "section": "情境族語", "a_pw": "nama’uda a qadav i tjanumun?", "a_zh": "你那裡的天氣如何？", "b_pw": "venalivali aravac imaza i tjanuamen.", "b_zh": "我們這裡颳大風。"}, {"id": 23, "page": 4, "section": "情境族語", "a_pw": "a qemudjaqudjalj anga?", "a_zh": "下雨了嗎？", "b_pw": "ui, naqemudjalj ta sauni, sa nameljay anga.", "b_zh": "是的，剛剛有下雨，現在雨停了。"}, {"id": 24, "page": 5, "section": "情境族語", "a_pw": "a qemudjalj?", "a_zh": "下雨？", "b_pw": "matu naqemudjalj pai, tjevetjeveng a ’adjalanan.", "b_zh": "好像下過雨，你看馬路是濕的。"}, {"id": 25, "page": 5, "section": "情境族語", "a_pw": "a qemudjaqudjalj? awua/aqua tjevetjeveng sun?", "a_zh": "有下雨嗎？你怎麼全身都濕了？", "b_pw": "qemudjaqudjalj i casav, ini a’en a namasikausua.", "b_zh": "外面在下雨，我沒有帶雨傘。"}, {"id": 26, "page": 5, "section": "情境族語", "a_pw": "ma’uda sun?", "a_zh": "你怎麼了", "b_pw": "mezangal aravac a qadav, sa malingac a’en", "b_zh": "太陽好大，曬得我頭好暈。"}, {"id": 27, "page": 5, "section": "情境族語", "a_pw": "ini a’en a paqenetj anga ’emacu ta ’inpic.", "a_zh": "我不記得帶筆了", "b_pw": "’u pasedjamay sun.", "b_zh": "我借你。"}, {"id": 28, "page": 5, "section": "情境族語", "a_pw": "ini a’en a paqenetj anga ’emacu ta qecap.", "a_zh": "我忘了帶筷子。", "b_pw": "ini a’en a na’emacu uta, ari velii!", "b_zh": "我也沒有帶，我們去買。"}, {"id": 29, "page": 5, "section": "情境族語", "a_pw": "ari velii ta ’inpic ui?", "a_zh": "我們去買筆好嗎？", "b_pw": "ui, sa uri veneli anan a’en ta siquliqulip.", "b_zh": "好，我還要買橡皮擦。"}, {"id": 30, "page": 6, "section": "情境族語", "a_pw": "anema uri su cengelj/incengeljen?", "a_zh": "你的中餐會是什麼？", "b_pw": "uri ’eman a’en ta sinancengelj i gakku.", "b_zh": "我要吃學校製作的午餐"}, {"id": 31, "page": 6, "section": "情境族語", "a_pw": "a vai’ itjen a semanmali?", "a_zh": "我們去打球嗎？", "b_pw": "ui, ari!", "b_zh": "好喔！我們走。"}, {"id": 32, "page": 6, "section": "情境族語", "a_pw": "a vai’ sun a ’iciul tjanuamen a semanmali ta yukiu?", "a_zh": "要不要跟我們去打棒球？", "b_pw": "ini a’en a vai’, uri vai’ a’en a ’itulu.", "b_zh": "不，我不去，我要讀書。"}, {"id": 33, "page": 6, "section": "情境族語", "a_pw": "alapan a’en ta suapan?", "a_zh": "可否幫我拿掃把？", "b_pw": "ni, uza suapan!", "b_zh": "這掃把給你。"}, {"id": 34, "page": 6, "section": "情境族語", "a_pw": "a ma’asuap anga sun?", "a_zh": "你掃好了嗎？", "b_pw": "ma’asuap anga a’en.", "b_zh": "我掃好了。"}, {"id": 35, "page": 6, "section": "情境族語", "a_pw": "’unga’ungay a ’asintan, pay sicsici!", "a_zh": "地板很髒，去擦一下。", "b_pw": "ui, malap anan a’en ta zuking.", "b_zh": "好，我去拿抹布。"}, {"id": 36, "page": 7, "section": "情境族語", "a_pw": "’ungay aravac aza qezung, sau sisici!", "a_zh": "那個窗戶很髒，去擦一下。", "b_pw": "galju anan, ’u pa’asuapay anan imaza.", "b_zh": "等一下，我先掃完這裡。"}, {"id": 37, "page": 7, "section": "情境族語", "a_pw": "uri ’emuda sun nusauni?", "a_zh": "你等一下要做什麼？", "b_pw": "uri vai’ a’en a ’emim tjai sinsi.", "b_zh": "我要去找老師。"}, {"id": 38, "page": 7, "section": "情境族語", "a_pw": "uri ’emuda timadju nu semu’a i gakku?", "a_zh": "她放學要做什麼？", "b_pw": "uri vai’ a’en a semenay ’ata ’u drava.", "b_zh": "我要跟朋友去唱歌。"}, {"id": 39, "page": 7, "section": "情境族語", "a_pw": "uri ’emuda timadju nu semu’a i gakku?", "a_zh": "她放學要做什麼？", "b_pw": "uri vai’ a ljemanguy timadju.", "b_zh": "他要去游泳。"}, {"id": 40, "page": 7, "section": "情境族語", "a_pw": "i tjumaq ti Ljavaus?", "a_zh": "請問Ljavaus在家嗎？", "b_pw": "ne’a i tjumaq timadju, anema su si’i’im?", "b_zh": "她不在，找他什麼事？"}, {"id": 41, "page": 7, "section": "情境族語", "a_pw": "’elju/idu ’ani ta kudamunu/suiku!", "a_zh": "我們來吃水果吧！", "b_pw": "ui, matu sasanguanguaqan aicu a mare’a kudamunu/suiku.", "b_zh": "好喔！這些水果看起來很棒。"}, {"id": 42, "page": 8, "section": "情境族語", "a_pw": "a palamu anga djemaljun itjen?", "a_zh": "我們快到了嗎？", "b_pw": "palamu anga, djemaljudjaljun anga itjen.", "b_zh": "快了，我們快到了。"}, {"id": 43, "page": 8, "section": "情境族語", "a_pw": "a djemaljun anga itjen?", "a_zh": "我們到了嗎？", "b_pw": "ini anan, cemadja anan.", "b_zh": "還沒到，還很遠。"}, {"id": 44, "page": 8, "section": "情境族語", "a_pw": "anema su pinacunan tucu a qadav?", "a_zh": "你今天看到了什麼？", "b_pw": "napacun a’en ta qatjuvi ’ata qayaqayam.", "b_zh": "我看到蛇，還有鳥。"}, {"id": 45, "page": 8, "section": "情境族語", "a_pw": "a nama’akisia a maTaitung timadju?", "a_zh": "他是搭火車去臺東嗎？", "b_pw": "ui, nama’akisia (a maTaitung) timadju?", "b_zh": "是，他搭火車去(臺東)。"}, {"id": 46, "page": 8, "section": "情境族語", "a_pw": "nu ma’abasu itjen a magimeng ma’apidalj a zikang?", "a_zh": "搭公車要多久才會到學校？", "b_pw": "nu tapuluq sa’a lima pungan a zikang djaljun i gakku/gimmeng.", "b_zh": "分鐘會到學校。"}, {"id": 47, "page": 8, "section": "情境族語", "a_pw": "cuay itjen a uniting nu vai’ itjen a maUlay?", "a_zh": "開車去烏來要很久嗎？", "b_pw": "tjara djemaljun ta icizikang.", "b_zh": "大約要一個小時。"}, {"id": 48, "page": 9, "section": "情境族語", "a_pw": "a saigu sun a ma’adidinsia?", "a_zh": "你會騎腳踏車嗎？", "b_pw": "saigu a’en a ma’adidinsia.", "b_zh": "我會騎腳踏車。"}, {"id": 49, "page": 9, "section": "情境族語", "a_pw": "a izua su utubay?", "a_zh": "你有摩托車嗎？", "b_pw": "izua ’u utubay.", "b_zh": "我有一台摩托車。"}, {"id": 50, "page": 9, "section": "情境族語", "a_pw": "a izua su utubay?", "a_zh": "你有摩托車嗎？", "b_pw": "ne’a nu ’u utubay.", "b_zh": "我沒有摩托車。"}, {"id": 51, "page": 9, "section": "情境族語", "a_pw": "pida anga su cavilj?", "a_zh": "你今年幾歲了？", "b_pw": "siva anga puluq sa’a alu a ’u cavilj.", "b_zh": "我已經98歲了。"}, {"id": 52, "page": 9, "section": "情境族語", "a_pw": "na’emasinu sun?", "a_zh": "你從哪裡來？", "b_pw": "na’emasi pucunug a’en.", "b_zh": "我來自文樂。"}, {"id": 53, "page": 9, "section": "情境族語", "a_pw": "a paiwan a su ce’elj auta?", "a_zh": "你的另一伴也是排灣族嗎？", "b_pw": "ini, seAmis timadju.", "b_zh": "不，她是阿美族人。"}, {"id": 54, "page": 10, "section": "情境族語", "a_pw": "masanpidalj a su ’inasaigu a ’ai?", "a_zh": "您會說哪些語言？", "b_pw": "saigu a’en a penaiwanan ’atua ’ai na seAmis.", "b_zh": "我會說排灣語和阿美語。"}, {"id": 55, "page": 10, "section": "情境族語", "a_pw": "anema su veliin?", "a_zh": "你要買什麼？", "b_pw": "uri veneli a’en tu ita ta kuppu.", "b_zh": "我要買一個杯子。"}, {"id": 56, "page": 10, "section": "情境族語", "a_pw": "veneli a’en ta vawa, a izua nu sipaveliveli?", "a_zh": "我要買米酒，你們有賣嗎？", "b_pw": "izua, uri pa’apida sun?", "b_zh": "有，你要買幾個？"}, {"id": 57, "page": 10, "section": "情境族語", "a_pw": "a izua nu sipaveliveli a savi’i?", "a_zh": "你們有賣檳榔嗎？", "b_pw": "ne’a, ini amen a paveliveli ta savi’i.", "b_zh": "沒有，我們沒有賣檳榔。"}, {"id": 58, "page": 10, "section": "情境族語", "a_pw": "veneli a’en ta djuadjuay a paday.", "a_zh": "我要買糯米。", "b_pw": "tjanupida a su veliin?", "b_zh": "你要買多少？"}, {"id": 59, "page": 10, "section": "情境族語", "a_pw": "veneli a’en ta vurati.", "a_zh": "我要買地瓜。", "b_pw": "mapuljat anga (a veliin) a vurati.", "b_zh": "地瓜都賣完了。"}, {"id": 60, "page": 11, "section": "情境族語", "a_pw": "veneli a’en ta qalev tu tjanudrusa.", "a_zh": "我要買兩瓶油。", "b_pw": "tjanuita anga a tjeza imaza.", "b_zh": "我們只剩一瓶。"}, {"id": 61, "page": 11, "section": "情境族語", "a_pw": "pidapida cu a paday?", "a_zh": "這包米多少錢？", "b_pw": "tjelu a day a tacavu.", "b_zh": "一包300元。"}, {"id": 62, "page": 11, "section": "情境族語", "a_pw": "maqati sun a pasedjaman ta paisu tjanua’en?", "a_zh": "可以借我錢嗎？", "b_pw": "pida su ’isedjamen?", "b_zh": "你要借多少？"}, {"id": 63, "page": 11, "section": "情境族語", "a_pw": "a maqati a’en a ’isedjaman ta su itung?", "a_zh": "我可以借你的衣服嗎？", "b_pw": "maqati, alapu a tisun.", "b_zh": "可以，自己拿"}, {"id": 64, "page": 11, "section": "情境族語", "a_pw": "a maqati a’en a ’isedjam tjanusun ta laqulj?", "a_zh": "我可以向你借書嗎？", "b_pw": "’u sinipasedjam anga tjai Vais.", "b_zh": "我借給Vais了。"}, {"id": 65, "page": 11, "section": "情境族語", "a_pw": "a maqati su pasedjaman a’en ta didinsia?", "a_zh": "請借給我你的腳踏車好嗎？", "b_pw": "maqati, paci’elu anga nutiav.", "b_zh": "可以，明天要還。"}, {"id": 66, "page": 12, "section": "情境族語", "a_pw": "nungida a’en a cemug ta ’u kiyam tjanusun?", "a_zh": "我什麼時候要還你錢？", "b_pw": "ini a ’emuda, cugu anga nu izua anga su paisu.", "b_zh": "沒關係，你有錢的時候再說。"}, {"id": 67, "page": 12, "section": "情境族語", "a_pw": "djavadjavay a masantalj, ti Sauniav a’en.", "a_zh": "大家好，我是Sauniav", "b_pw": "ui, djavadjavay sun uta Sauniav.", "b_zh": "Sauniyaw你好。"}, {"id": 68, "page": 12, "section": "情境族語", "a_pw": "a ti Apang timdju?", "a_zh": "他是Apang嗎？", "b_pw": "ui, ti Apang timadju.", "b_zh": "是，他是Apang。"}, {"id": 69, "page": 12, "section": "情境族語", "a_pw": "a ti Drangadrang sun?", "a_zh": "你是Drangadrang嗎？", "b_pw": "ini, ti Camak a’en.", "b_zh": "不是，我是Camak。"}, {"id": 70, "page": 12, "section": "情境族語", "a_pw": "tima ti Apang?", "a_zh": "誰是Apang？", "b_pw": "’u qali a ti Apang.", "b_zh": "Apang是我的朋友。"}, {"id": 71, "page": 12, "section": "情境族語", "a_pw": "tima ngadaan na za su siruvetje’ a vavayan a tjavulung tjanusun?", "a_zh": "你姐姐的名字是什麼？", "b_pw": "ti Tjuku a ngadaan ni kaka/’a’a", "b_zh": "我的姐姐的名字是Tjuku。"}, {"id": 72, "page": 13, "section": "情境族語", "a_pw": "tima ngadaan na su siruvetje’ a vavayan a tjaljalja’ tjanusun?", "a_zh": "你妹妹的名字是什麼？", "b_pw": "ti Vais a ngadaan nimadju.", "b_zh": "我的妹妹的名字是Vais。"}, {"id": 73, "page": 13, "section": "情境族語", "a_pw": "a ’emeljang sun ta ngadaan nimadju?", "a_zh": "你知道他的名字嗎？", "b_pw": "ti Apang a ngadaan nimadju.", "b_zh": "他叫做Apang。"}, {"id": 74, "page": 13, "section": "情境族語", "a_pw": "pida anga a cavilj ni su kaka a uqaljay?", "a_zh": "你哥哥今年已幾歲？", "b_pw": "tapuluq anga sa’a lima a cavilj nimadju.", "b_zh": "他今年15歲了。"}, {"id": 75, "page": 13, "section": "情境族語", "a_pw": "anema a sengesengan ni tjaina?", "a_zh": "你媽媽從事什麼工作？", "b_pw": "sivitay timadju.", "b_zh": "她是軍人。"}, {"id": 76, "page": 13, "section": "情境族語", "a_pw": "anema a sengesengan ni tjama?", "a_zh": "你的爸爸從事什麼工作？", "b_pw": "sinsi timadju.", "b_zh": "他是老師。"}, {"id": 77, "page": 13, "section": "情境族語", "a_pw": "maljepida tiamadju a tace’eljan?", "a_zh": "他們全家有幾個人？", "b_pw": "malje lima tiamadju a tace’eljan.", "b_zh": "他們全家有五個人。"}, {"id": 78, "page": 14, "section": "情境族語", "a_pw": "mapida mare’a su siruvestje’ a tjaljalja’ tjanusun?", "a_zh": "你有幾個弟弟妹妹？", "b_pw": "ne’a nu ’u siruvetje’ a uqaljay a tjaljalja’ tjanua’en, lja’ua matjelu a vavayavayan.", "b_zh": "我沒有弟弟，但有三個妹妹"}, {"id": 79, "page": 14, "section": "情境族語", "a_pw": "mapida su siruvetje’ a tjavavulungan tjanusun?", "a_zh": "你有幾個兄姊？", "b_pw": "ne’a lja ’u kaka a tjavulung tjanua’en.", "b_zh": "我沒有兄姊。"}, {"id": 80, "page": 14, "section": "情境族語", "a_pw": "a marevetje’ mun?", "a_zh": "你們是兄弟嗎？", "b_pw": "ui, ljema kaka a’en tjaimadju.", "b_zh": "是的，我稱他為kaka"}, {"id": 81, "page": 14, "section": "情境族語", "a_pw": "a paiwan mun?", "a_zh": "你們是原住民嗎？", "b_pw": "ui, paiwan amen.", "b_zh": "是，我們是原住民。"}, {"id": 82, "page": 14, "section": "情境族語", "a_pw": "a sepaiwan zuku timadju uta?", "a_zh": "她也是排灣族人嗎？", "b_pw": "ui, paiwan zuku timadju uta.", "b_zh": "是的，她也是排灣族人。"}, {"id": 83, "page": 14, "section": "情境族語", "a_pw": "nama’uda a qadav tucu?", "a_zh": "今天天氣如何？", "b_pw": "ljemaljeqeljeqel a pagalju, te’eli ta maculjuculju a zaljum.", "b_zh": "天氣有點冷，要多喝熱水。"}, {"id": 84, "page": 15, "section": "情境族語", "a_pw": "nama’uda a qadav tucu?", "a_zh": "今天天氣如何？", "b_pw": "paruzemulzulzul tucu, te’eli a semuqaca ta zaljum.", "b_zh": "天氣有點熱，我們要多喝水。"}, {"id": 85, "page": 15, "section": "情境族語", "a_pw": "a tjengelay sun ta ’aljavevean?", "a_zh": "你喜歡春天嗎？", "b_pw": "tjengelay a’en ta ’aljavevean, sarenguanguaq a vali.", "b_zh": "我喜歡春天，天氣很溫暖。"}, {"id": 86, "page": 15, "section": "情境族語", "a_pw": "tjengelay sun ta ’aljauraman?", "a_zh": "你喜歡秋天嗎？", "b_pw": "ini a’en a tjengelay ta ’aljauraman, ruvali anga nu ’aljauraman", "b_zh": "我不喜歡秋天，秋天有好多颱風。"}, {"id": 87, "page": 15, "section": "情境族語", "a_pw": "ini a’en a paqenetj anga a ’emacu tua laqulj.", "a_zh": "我忘了帶課本。", "b_pw": "tja pacunay a madrusa.", "b_zh": "我們一起看"}, {"id": 88, "page": 15, "section": "情境族語", "a_pw": "ini a’en a paqenetj anga a ’emacu tua siquliqulip.", "a_zh": "我忘了帶橡皮擦。", "b_pw": "’u pasedjamay sun.", "b_zh": "我借你。"}, {"id": 89, "page": 15, "section": "情境族語", "a_pw": "anema uri su cengelj?", "a_zh": "你午餐要吃什麼？", "b_pw": "uri ’eman a’en tua minpaw.", "b_zh": "我要吃麵包。"}, {"id": 90, "page": 16, "section": "情境族語", "a_pw": "anema uri su ’aiven?", "a_zh": "你晚餐要吃什麼？", "b_pw": "uri ’eman a’en ta ’insa.", "b_zh": "我要吃飯。"}, {"id": 91, "page": 16, "section": "情境族語", "a_pw": "anema su ’enamain?", "a_zh": "你早餐吃了什麼？", "b_pw": "na’eman a’en tua qacilu.", "b_zh": "我吃了蛋。"}, {"id": 92, "page": 16, "section": "情境族語", "a_pw": "anema su cengelj?", "a_zh": "你午餐吃了什麼？", "b_pw": "na’eman a’en ta kuka.", "b_zh": "我吃了雞肉。"}, {"id": 93, "page": 16, "section": "情境族語", "a_pw": "ari a ljemanguy.", "a_zh": "我們去游泳。", "b_pw": "ui, ari!", "b_zh": "好啊！我們一起去。"}, {"id": 94, "page": 16, "section": "情境族語", "a_pw": "a na’imuremur anga sun?", "a_zh": "你漱口了嗎", "b_pw": "ini anan, semenasenav anan a’en tua ’isi.", "b_zh": "還沒，我正在洗碗。"}, {"id": 95, "page": 16, "section": "情境族語", "a_pw": "a namenuremur anga sun?", "a_zh": "你漱口了嗎？", "b_pw": "namenuremur anga a’en", "b_zh": "我漱口了。"}, {"id": 96, "page": 17, "section": "情境族語", "a_pw": "a nasemenav anga sun tua ’isi?", "a_zh": "你洗碗了嗎？", "b_pw": "ma’asenav anga a’en tua ’u ’isi.", "b_zh": "我的碗洗好了。"}, {"id": 97, "page": 17, "section": "情境族語", "a_pw": "nu ma’aya sun i gimeng, anema ru/uri su ’udain?", "a_zh": "你放學要做什麼？", "b_pw": "uri puntalj a’en a tjumaq.", "b_zh": "我要直接回家。"}, {"id": 98, "page": 17, "section": "情境族語", "a_pw": "uri kemuda timadju nu qemacuvung tua tja kitulu i gakku?", "a_zh": "她放學要做什麼？", "b_pw": "uri vai’ a iyugi timadju.", "b_zh": "她要去跳舞。"}, {"id": 99, "page": 17, "section": "情境族語", "a_pw": "Ljumeg, a i tjumaq sun?", "a_zh": "Ljumeg，你在家嗎？", "b_pw": "\u0000izua, saumaqanu.", "b_zh": "在，快進來。"}, {"id": 100, "page": 17, "section": "情境族語", "a_pw": "vuvu, mangtjez a’en a paljilji tjanusun.", "a_zh": "奶奶，我來看你了。", "b_pw": "sicuayan anga su pinangtjezan, nasengelit anga a’en tjanusun.", "b_zh": "你好久沒來了，我好想念你。"}, {"id": 101, "page": 17, "section": "情境族語", "a_pw": "Vais, idu ’ivangavangi.", "a_zh": "Vais，我們一起玩。", "b_pw": "saqumaqanu a ’irimu, cuay anga a’en a ’iljaljavaljava tjanusun.", "b_zh": "快進來，我等你好久。"}, {"id": 102, "page": 18, "section": "情境族語", "a_pw": "a ’eman sun ta tjianes?", "a_zh": "你要吃橘子嗎？", "b_pw": "ini a’en a ’eman ta tjianes, avanay a pingku.", "b_zh": "我不能吃橘子，我吃蘋果就好。"}, {"id": 103, "page": 18, "section": "情境族語", "a_pw": "suliavu a ’eman, liav anan.", "a_zh": "吃多點，還很多。", "b_pw": "sa pai numaya.", "b_zh": "我不客氣了呦！"}, {"id": 104, "page": 18, "section": "情境族語", "a_pw": "suliavu, liav anan.", "a_zh": "多吃點，還很多。", "b_pw": "semuliav anga a’en, ini a’en a ’eman anga.", "b_zh": "我吃多了，不吃了。"}, {"id": 105, "page": 18, "section": "情境族語", "a_pw": "uri sema inu itjen tucu a qadav?", "a_zh": "我們今天要去哪裡？", "b_pw": "uri ’acuin itjen ni sinsi a sema pana.", "b_zh": "老師要帶我們去河邊。"}, {"id": 106, "page": 18, "section": "情境族語", "a_pw": "a uri sema pana itjen tucu a qadav?", "a_zh": "我們今天要去河邊嗎？", "b_pw": "ini, uri ’acuin itjen ni sinsi a sema gade.", "b_zh": "不是，老師要帶我們去山上。"}, {"id": 107, "page": 18, "section": "情境族語", "a_pw": "sinsi, anema uri tja pacunan i pana?", "a_zh": "老師，我們到河邊要看什麼？", "b_pw": "ari vai’i a pacun ta quljicacenglav.", "b_zh": "我們去看蜻蜓。"}, {"id": 108, "page": 19, "section": "情境族語", "a_pw": "sinsi, anema uri tja pacunan i gade?", "a_zh": "老師，我們到山上要看什麼？", "b_pw": "ari vai’ a pacun ta kadjiadji.", "b_zh": "我們去看蝴蝶。"}, {"id": 109, "page": 19, "section": "情境族語", "a_pw": "sinsi, a vai’ itjen a sema pana a ljemanguy?", "a_zh": "老師，我們要到河邊游泳嗎？", "b_pw": "ini, uri vai’ itjen a pacun ta quljicacenglav.", "b_zh": "不是，我們要去看蜻蜓。"}, {"id": 110, "page": 19, "section": "情境族語", "a_pw": "sinsi, a vai’ itjen a sema vavua a temalen ta ljaceng?", "a_zh": "老師，我們要到田裡種菜嗎？", "b_pw": "uri vai’ itjen a temuvulj tucu.", "b_zh": "我們今天要去挖土。"}, {"id": 111, "page": 19, "section": "情境族語", "a_pw": "izua a kadjiadji a minlayalayap i zua.", "a_zh": "那裡有蝴蝶飛來飛去。", "b_pw": "ini a kadjiadji azua, tjainan azua.", "b_zh": "那不是蝴蝶，那是蜜蜂。"}, {"id": 112, "page": 19, "section": "情境族語", "a_pw": "anema uri su pa’azuanan a sema tapav?", "a_zh": "你怎麼去工寮？", "b_pw": "uri unting a’en ta haya a sema tapav.", "b_zh": "我開車去工寮。"}, {"id": 113, "page": 19, "section": "情境族語", "a_pw": "anema uri pa’azuanan a sema biyuing nimadju?", "a_zh": "他怎麼去醫院？", "b_pw": "uri djemavac timadju.", "b_zh": "他走路去醫院。"}, {"id": 114, "page": 20, "section": "情境族語", "a_pw": "anema su pina’azuanan a tjumaq?", "a_zh": "你搭什麼回家？已經到家", "b_pw": "nama’a kisiya a’en a tjumaq.", "b_zh": "我搭火車回家。已經到家"}, {"id": 115, "page": 20, "section": "情境族語", "a_pw": "anema pina’azuanan ni Sauniyav a sema gakku?", "a_zh": "Sauniyaw搭什麼去學校？", "b_pw": "nama’a kisiya ti Sauniyav a sema gakku.", "b_zh": "Saniyaw搭火車去學校。"}, {"id": 116, "page": 20, "section": "情境族語", "a_pw": "a nama’a tjiyin sun a sema gakku?", "a_zh": "你搭捷運上學嗎？", "b_pw": "ini, ma’abasu a’en a sema gakku.", "b_zh": "不是，我搭公車上學。"}, {"id": 117, "page": 20, "section": "情境族語", "a_pw": "a nama’a palidring sun a sema gakku?", "a_zh": "你騎腳踏車上學嗎？", "b_pw": "ui, ma’apalidring a’en a sema gakku.", "b_zh": "對，我騎腳踏車上學。"}, {"id": 118, "page": 20, "section": "情境族語", "a_pw": "a nama’a kauti sun a sema Takau?", "a_zh": "你搭高鐵去高雄嗎？", "b_pw": "ui, nama’a kauti a’en a sema Takav.", "b_zh": "對，我搭高鐵去高雄。"}, {"id": 119, "page": 20, "section": "情境族語", "a_pw": "tjungu a yubinkiuku tua gakku?", "a_zh": "郵局離學校近嗎？", "b_pw": "i tjungu, tja djavacen.", "b_zh": "很近，走路就會到。"}, {"id": 120, "page": 21, "section": "情境族語", "a_pw": "a djemet a ’a’anan ta za sase’ezan?", "a_zh": "餐廳離車站近嗎？", "b_pw": "nu tjevuta itjen itua sase’ezan, djemavac a palamu sa djaljun.", "b_zh": "出車站再走一下就到了。"}, {"id": 121, "page": 21, "section": "情境族語", "a_pw": "a maqati a’en a lemuing? tu uri ’u sipuveci’.", "a_zh": "我可以錄音嗎？作為紀錄", "b_pw": "maqati.", "b_zh": "可以"}, {"id": 122, "page": 21, "section": "情境族語", "a_pw": "anema anga su sengsengan tucu?", "a_zh": "那你現在有工作嗎？", "b_pw": "i gakku a’en a murisengsengsengan.", "b_zh": "我在學校上班。"}, {"id": 123, "page": 21, "section": "情境族語", "a_pw": "a i qinaljaan a su alja’ auta?", "a_zh": "你孩子也在部落嗎？", "b_pw": "ini, i lizulizu’ a ’u alja’.", "b_zh": "不，我孩子住在都市"}, {"id": 124, "page": 21, "section": "情境族語", "a_pw": "veneli anan a’en ta qacilu, a izua anan a qacilu?", "a_zh": "我還要買蛋，你們有嗎？", "b_pw": "mapuljat anga nia qacilu.", "b_zh": "我們的蛋沒剩了"}, {"id": 125, "page": 21, "section": "情境族語", "a_pw": "nama’uda a su ’inatjengelayan a itung?", "a_zh": "你想要什麼樣子的衣服呢？", "b_pw": "saveneli a’en ta itung a drikidrikitj a siuc.", "b_zh": "我要買短袖的衣服"}, {"id": 126, "page": 22, "section": "情境族語", "a_pw": "a izua anan a maljian a quljav?", "a_zh": "有別的顏色嗎？", "b_pw": "izua anan nimitja a vuqavuqalj ’atua cangiangia a quljav.", "b_zh": "我們還有白色和藍色。"}, {"id": 127, "page": 22, "section": "情境族語", "a_pw": "pidapida cu a ljaceng?", "a_zh": "這菜多少錢？", "b_pw": "drusa a puluq a vatan a ljaceng nu tadjaljeng.", "b_zh": "菜一把20元。"}, {"id": 128, "page": 22, "section": "情境族語", "a_pw": "pidapida cu a vurati?", "a_zh": "這個地瓜多少錢？", "b_pw": "tjelu a puluq a vatan a vurati nu tatjingtjingan.", "b_zh": "地瓜一斤30元。"}, {"id": 129, "page": 22, "section": "情境族語", "a_pw": "Keljeng, a ti Kuljelje a napasedjam tjanusun tu ca uba?", "a_zh": "Keljeng，這個外套是Kuljelje借你的嗎？", "b_pw": "ini, vineli cu ni ’ina tjanua’en.", "b_zh": "不是，這是我媽媽買給我的。"}, {"id": 130, "page": 22, "section": "情境族語", "a_pw": "nungida su paci’elen?", "a_zh": "那你什麼時候要還？", "b_pw": "nutiav ’u paci’elav anga tjimadju.", "b_zh": "我明天就還給他。"}, {"id": 131, "page": 22, "section": "情境族語", "a_pw": "pininu a dru’udru’ung a tja’it?", "a_zh": "鐮刀放在哪裡？", "b_pw": "pinigidi ta dradra’uyan, i tjungu ta siqeljevan na ubav.", "b_zh": "在簍子旁，倉庫的門邊。"}, {"id": 132, "page": 23, "section": "情境族語", "a_pw": "ma’uda sun?", "a_zh": "你怎麼了？", "b_pw": "pasa mutjautjaq a’en, vai’ a’en a sema tua papilimaan.", "b_zh": "我想吐，我要去洗手台"}, {"id": 133, "page": 23, "section": "情境族語", "a_pw": "sinsi, saqetju a ’u tjialj, vai’ a’en a sema binziyu.", "a_zh": "老師，我肚子痛，我要先去廁所。", "b_pw": "ui, pa’irimu.", "b_zh": "好，快一點去。"}, {"id": 134, "page": 23, "section": "情境族語", "a_pw": "a maqati a’en a sema binziyu?", "a_zh": "我可以去廁所嗎？", "b_pw": "palamu anga itjen a semu’a, vai’u anga nusauni.", "b_zh": "我們快結束了，等一下再去。"}, {"id": 135, "page": 23, "section": "情境族語", "a_pw": "izainu ti Muni?", "a_zh": "Muni在哪裡？", "b_pw": "saqetju a tjialj nimadju, izua anan i binziyu.", "b_zh": "她肚子痛，她在廁所。"}, {"id": 136, "page": 23, "section": "情境族語", "a_pw": "aqua ini a mangetjez ti Muni?", "a_zh": "Muni為甚麼沒來？", "b_pw": "masezasezam timadju.", "b_zh": "她發燒了。"}, {"id": 137, "page": 23, "section": "情境族語", "a_pw": "pay, pasemalavi amen tu tima sun?", "a_zh": "請自我介紹。", "b_pw": "ti Tjanubak a ’u ngadaan, a lja Tjaluigi, tapuluq anga ’u cavilj.", "b_zh": "我叫Tjanubak Tjaluigi，我今年10歲。"}, {"id": 138, "page": 24, "section": "情境族語", "a_pw": "senema sun a zukuan?", "a_zh": "你是哪一族的小孩？", "b_pw": "sepaiwan a’en.", "b_zh": "我是排灣族"}, {"id": 139, "page": 24, "section": "情境族語", "a_pw": "tima su ’ina su ’ama?", "a_zh": "你的父母親是誰？", "b_pw": "lja Tjaluigi a’en a ti Camak.", "b_zh": "我是Camak，Tjaluigi家成員"}, {"id": 140, "page": 24, "section": "情境族語", "a_pw": "mainu sun?", "a_zh": "你要去哪裡？", "b_pw": "uri vai’ a’en a magakku a ’emim tjaisinsi.", "b_zh": "我要去學校(教室)找老師"}, {"id": 141, "page": 24, "section": "情境族語", "a_pw": "uri semainu ti Puljaljuyan?", "a_zh": "Puljaljuyan要去哪裡？", "b_pw": "uri vai’ a veneric ta cemel timadju.", "b_zh": "他要去丟垃圾。"}, {"id": 142, "page": 24, "section": "情境族語", "a_pw": "i zainu ti Muni?", "a_zh": "Muni在哪裡？", "b_pw": "i zua anga itua ljaljanguyan, uri ’ilalumalj ta ma’ava’av timadju nusauni.", "b_zh": "已在游泳池，他等一下參與游泳比賽。"}, {"id": 143, "page": 24, "section": "情境族語", "a_pw": "a izua uri su ’icapiljen nu undukay tu azua i qadav?", "a_zh": "運動會那天你有參賽嗎？", "b_pw": "ui, uri ’icapilj a’en ta mekelj.", "b_zh": "會啊，我會比賽跑步。"}, {"id": 144, "page": 25, "section": "情境族語", "a_pw": "anema uri tja ’udain nu undukadukay i qadav?", "a_zh": "我們運動會那天要做甚麼？", "b_pw": "uri ’ilalumalj itjen tua maqaqesir.", "b_zh": "我們要比賽拔河。"}, {"id": 145, "page": 25, "section": "情境族語", "a_pw": "a i tjumaq ti ’acumusu i vavayan?", "a_zh": "奶奶在家嗎？", "b_pw": "ui, nataqed i qumaqan.", "b_zh": "在，她在房間睡覺。"}, {"id": 146, "page": 25, "section": "情境族語", "a_pw": "a i tjumaq ti ’acumusu i uqaljay?", "a_zh": "爺爺在家嗎？", "b_pw": "izua i vavav timadju, sau ’imu.", "b_zh": "他在二樓，你上去找吧。"}, {"id": 147, "page": 25, "section": "情境族語", "a_pw": "izainu ti tjama?", "a_zh": "你的爸爸在哪裡？", "b_pw": "seman djamadjamay i ’a’esan timadju, ’u vai’av a qivu.", "b_zh": "他在廚房炒菜，我去叫他。"}, {"id": 148, "page": 25, "section": "情境族語", "a_pw": "mainu anga ti Muni?", "a_zh": "Muni去哪裡了？", "b_pw": "vai’ anga timadju a sema pukukaan a ’ikuka.", "b_zh": "她去雞寮抓雞了。"}, {"id": 149, "page": 25, "section": "情境族語", "a_pw": "a maqati itjen a mecevung nutiav a masu’incengelj?", "a_zh": "我和您約明天下午好嗎？", "b_pw": "maqati, a cevungi anga izainu?", "b_zh": "可以，我們約哪裡見面？"}, {"id": 150, "page": 26, "section": "情境族語", "a_pw": "aqu cemi’el sun a maqinaljaan?", "a_zh": "為什麼你回部落？", "b_pw": "uri vai’ a’en a ’isansinsi a temulu.", "b_zh": "我要回去教書。"}, {"id": 151, "page": 26, "section": "情境族語", "a_pw": "aqu sa’itulu sun ta tjemenun?", "a_zh": "你怎麼會想要學織布？", "b_pw": "niamen cu a ’a’udaan a tjemenun, sapatavela’ a’en ta tjaivelivililj.", "b_zh": "織布是我們的文化，我想要讓文化延續。"}, {"id": 152, "page": 26, "section": "情境族語", "a_pw": "tjengelay a’en ta i cu a itung, pida a cu (a avelian)?", "a_zh": "我喜歡這件衣服，多少錢？", "b_pw": "lima a iday a zua.", "b_zh": "那件500元"}, {"id": 153, "page": 26, "section": "情境族語", "a_pw": "pida avelian na itung?", "a_zh": "請問衣服多少錢？", "b_pw": "tjelu a iday sa’a lima puluq a vatan a taita a itung, sa nu tjelu, ’uzulj.", "b_zh": "衣服一件350元，衣服三件1000元。"}, {"id": 154, "page": 27, "section": "12年國教族語", "a_pw": "anema cu?", "a_zh": "這是什麼？", "b_pw": "cukui cu.", "b_zh": "這是桌子。"}, {"id": 155, "page": 27, "section": "12年國教族語", "a_pw": "a sadjeludjelung cu a cukui?", "a_zh": "這張桌子很重嗎？", "b_pw": "ui, sadjelung aravac.", "b_zh": "是/對，這張桌子很重。"}, {"id": 156, "page": 27, "section": "12年國教族語", "a_pw": "tima zua?", "a_zh": "那是誰？", "b_pw": "’u ’ina a zua.", "b_zh": "那是我的媽媽。"}, {"id": 157, "page": 27, "section": "12年國教族語", "a_pw": "anema sengsengan ni tjaina?", "a_zh": "你媽媽做什麼工作？", "b_pw": "na’isan’emesa ti ’ina.", "b_zh": "我媽媽是廚師。"}, {"id": 158, "page": 27, "section": "12年國教族語", "a_pw": "a izua a laqulj i cukui?", "a_zh": "桌子上面有書嗎？", "b_pw": "izua a tjelu a laqulj a pinivavav ta cukui.", "b_zh": "有三本書放在桌上。"}, {"id": 159, "page": 27, "section": "12年國教族語", "a_pw": "nima cu a qudjidjilj a laqulj?", "a_zh": "紅色的書是誰的？", "b_pw": "ni sinsi aza qudjidjilj a laqulj.", "b_zh": "那本紅色的書是老師的。"}, {"id": 160, "page": 28, "section": "12年國教族語", "a_pw": "iyainuan a nu umaq?", "a_zh": "你們的家在哪裡？", "b_pw": "i gade a nia umaq.", "b_zh": "我們家在山上。"}, {"id": 161, "page": 28, "section": "12年國教族語", "a_pw": "a na’idjemet a su umaq ta gakku?", "a_zh": "妳家離學校很近嗎？", "b_pw": "ini, cemadja a pagalju.", "b_zh": "不是，有點遠。"}, {"id": 162, "page": 28, "section": "12年國教族語", "a_pw": "tjaljatjenglayan sun ta nema nu unduan?", "a_zh": "你最喜歡什麼運動？", "b_pw": "tjaljatjenglayan a’en ta ljemanguy.", "b_zh": "我最喜歡游泳。"}, {"id": 163, "page": 28, "section": "12年國教族語", "a_pw": "a natjemalupung ti ’ina ta vai’ a casav?", "a_zh": "媽媽外出時，有戴帽子嗎？", "b_pw": "ini, ini anga paqenetj ti ’ina a tjemalupung.", "b_zh": "沒有，媽媽忘了戴帽子。"}, {"id": 164, "page": 28, "section": "12年國教族語", "a_pw": "a nanguangaq a qadav tucu?", "a_zh": "今天天氣好嗎？", "b_pw": "ini, qemudjaqudjalj tucu.", "b_zh": "不，正在下雨。"}, {"id": 165, "page": 28, "section": "12年國教族語", "a_pw": "maqati a’en a vai’ a ’ivangavang a casav nu masu’incengelj?", "a_zh": "下午我可以出去玩嗎？ (請求同意)", "b_pw": "na’uya, maya anan a casav a ’ivangavang.", "b_zh": "不可以， 請先別出去玩！"}, {"id": 166, "page": 29, "section": "12年國教族語", "a_pw": "nu meljay a qudjalj, a maqati a’en a vai’ a casav a ’ivangavang?", "a_zh": "如果雨停了，我可以出去玩嗎？", "b_pw": "nu meljay anga, vai’u anga a casav a ’ivangavang.", "b_zh": "如果雨停了，你可以出去玩。"}, {"id": 167, "page": 29, "section": "12年國教族語", "a_pw": "nancibi/nanciubi tucu?", "a_zh": "今天是星期幾？", "b_pw": "niciubi tucu", "b_zh": "今天是星期日。"}, {"id": 168, "page": 29, "section": "12年國教族語", "a_pw": "numaitazua, tjitjumaqu sa’amaya, si’uda a casav.", "a_zh": "既然如此，你們只能留在家裡，不要出去。", "b_pw": "ui, ’emeljang amen.", "b_zh": "是的，我們知道了。"}, {"id": 169, "page": 29, "section": "12年國教族語", "a_pw": "tjainu a tjadjaljav a ma’akisia ’atua ma’abasu?", "a_zh": "搭火車和撘公車哪一個比較快？", "b_pw": "tjadjaljav a ma’akisia.", "b_zh": "搭火車比較快。"}, {"id": 170, "page": 29, "section": "12年國教族語", "a_pw": "a izua gade i tua nu qinaljaan?", "a_zh": "你們的部落有山嗎？", "b_pw": "izua, itua calisilisi a ’inizuanan na nia qinaljaan.", "b_zh": "有，而且我們部落座落在斜坡地(形)"}, {"id": 171, "page": 29, "section": "12年國教族語", "a_pw": "’u ’ivadaqay sun pai, izainu a i tjagaraus?", "a_zh": "我請問你，大武山在哪裡？", "b_pw": "i pasa ’acedas a i tjagaraus.", "b_zh": "大武山在東邊。"}, {"id": 172, "page": 30, "section": "12年國教族語", "a_pw": "ma’ainu a sematjalja’avus?", "a_zh": "往來義村怎麼走？", "b_pw": "susuu tu ca icu a djalan ’isun a djemaljun.", "b_zh": "你順著這條路走就到了。"}, {"id": 173, "page": 30, "section": "12年國教族語", "a_pw": "tu nama’uda a ljave’ nu tja te’elen?", "a_zh": "海水是什麼味道？", "b_pw": "qapedapedang a ljave’.", "b_zh": "海水是鹹鹹的。"}, {"id": 174, "page": 30, "section": "12年國教族語", "a_pw": "izau nemanema i ljave’?", "a_zh": "海裡有哪些動物？", "b_pw": "izua ciqav, quzang, mre’a gaang.", "b_zh": "有魚、蝦、蟹類。"}, {"id": 175, "page": 30, "section": "12年國教族語", "a_pw": "pida ’ula na gaang?", "a_zh": "螃蟹有幾隻腳？", "b_pw": "izua alu a ’ula na gaang", "b_zh": "螃蟹有八隻腳。"}, {"id": 176, "page": 30, "section": "12年國教族語", "a_pw": "anema a su sa’emanen?", "a_zh": "你想吃什麼？", "b_pw": "izua ’inesa a paday?", "b_zh": "有米飯嗎？"}, {"id": 177, "page": 30, "section": "12年國教族語", "a_pw": "anema su ’atjengelayan a ’eman?", "a_zh": "你喜歡吃些什麼？", "b_pw": "tjengelay a’en a ’eman ta ’inesa a paday, sa tisun?", "b_zh": "我喜歡吃米飯，那你呢？"}, {"id": 178, "page": 31, "section": "12年國教族語", "a_pw": "a ’eman sun ta macacam?", "a_zh": "你會吃辣嗎？", "b_pw": "ini, ini a’en a maqati a ’eman ta macacam.", "b_zh": "不，我不能吃辣。"}, {"id": 179, "page": 31, "section": "12年國教族語", "a_pw": "anemanema a su veliin?", "a_zh": "你要買哪些東西？", "b_pw": "ita a ’inpic, sa ita a laqulj a vaveci’an.", "b_zh": "一支鉛筆和一本筆記簿。"}, {"id": 180, "page": 31, "section": "12年國教族語", "a_pw": "saigu sun a penaiwanan?", "a_zh": "你會說排灣話嗎？", "b_pw": "saigu a’en a pagaljugzlju.", "b_zh": "我會一點點。"}, {"id": 181, "page": 31, "section": "12年國教族語", "a_pw": "na’asinu sun a ’icaquan ta aicu a pinaiwanan?", "a_zh": "你在哪裡學排灣話的？", "b_pw": "i gakku a’en ’icaquaquan", "b_zh": "我正在學校學"}, {"id": 182, "page": 31, "section": "12年國教族語", "a_pw": "a seAmis mun?", "a_zh": "你們是阿美族嗎？", "b_pw": "ini, sepaiwan amen.", "b_zh": "不是，我們是排灣族。"}, {"id": 183, "page": 31, "section": "12年國教族語", "a_pw": "napacun anga sun ta zua laqulj a gemalagalalj?", "a_zh": "你讀過那本鬼故事書嗎？", "b_pw": "ui, napacun anga a’en, talidu angata.", "b_zh": "有啊，我讀過。我覺得很有趣。"}, {"id": 184, "page": 32, "section": "句型篇國中", "a_pw": "ma’uda sun?", "a_zh": "你怎麼啦？", "b_pw": "saqetju a za ’u maca.", "b_zh": "我的眼睛痛。"}, {"id": 185, "page": 32, "section": "句型篇國中", "a_pw": "ma’uda sun?", "a_zh": "你怎麼啦？", "b_pw": "saqetju a ’u qulu.", "b_zh": "我的頭很痛。"}, {"id": 186, "page": 32, "section": "句型篇國中", "a_pw": "pida a vatu a pinaquzip na za ’edrian?", "a_zh": "這個小孩養了幾隻狗？", "b_pw": "ita a vatu nimadju.", "b_zh": "他有一隻狗。"}, {"id": 187, "page": 32, "section": "句型篇國中", "a_pw": "pida su laqulj?", "a_zh": "你有幾本書？", "b_pw": "drusa a ’u laqulj.", "b_zh": "我有二本書。"}, {"id": 188, "page": 32, "section": "句型篇國中", "a_pw": "nanzi anga?", "a_zh": "現在是幾點鐘？", "b_pw": "sicizikang anga.", "b_zh": "現在是四點鐘。"}, {"id": 189, "page": 32, "section": "句型篇國中", "a_pw": "nanzi nu paceged sun?", "a_zh": "你早上幾點鐘起床？", "b_pw": "lukuzi a paceged a’en nu ’adjamadjaman.", "b_zh": "我早上六點鐘起床。"}, {"id": 190, "page": 33, "section": "句型篇國中", "a_pw": "nanzi nu taqed sun?", "a_zh": "你晚上幾點鐘睡覺？", "b_pw": "nu ziuzi nataqed anga a’en.", "b_zh": "我晚上10點就睡了"}, {"id": 191, "page": 33, "section": "句型篇國中", "a_pw": "ainu anga ’u ’inpic?", "a_zh": "我的筆在哪裡？", "b_pw": "dacu a su ’inpic.", "b_zh": "你的筆在這裡。"}, {"id": 192, "page": 33, "section": "句型篇國中", "a_pw": "ainu anga ti tjama?", "a_zh": "你爸爸在哪裡？", "b_pw": "i gakku ti ’ama.", "b_zh": "我爸爸在學校裡。"}, {"id": 193, "page": 33, "section": "句型篇國中", "a_pw": "izainuan a nu umaq?", "a_zh": "你們家在哪裡？", "b_pw": "i gade a nia umaq.", "b_zh": "我們家在山上。"}, {"id": 194, "page": 33, "section": "句型篇國中", "a_pw": "pasainu sun tucu?", "a_zh": "你現在要往哪兒去？", "b_pw": "vai’ a’en a tjumaq.", "b_zh": "我正要回家。"}, {"id": 195, "page": 33, "section": "句型篇國中", "a_pw": "na’asinu mun tatiav?", "a_zh": "你們昨天去哪裡？", "b_pw": "na vai’ amen a gemadean tatiav.", "b_zh": "我們昨天去山上。"}, {"id": 196, "page": 34, "section": "句型篇國中", "a_pw": "uri mainu sun nutiav?", "a_zh": "你明天要去哪裡？", "b_pw": "uri vai’ a’en a magade nutiav.", "b_zh": "我明天要去山上。"}, {"id": 197, "page": 34, "section": "句型篇國中", "a_pw": "nima cu a alja’?", "a_zh": "這是誰的小孩？", "b_pw": "alja’ cu nimadju.", "b_zh": "這是她的小孩。"}, {"id": 198, "page": 34, "section": "句型篇國中", "a_pw": "a vurati azua?", "a_zh": "那是地瓜嗎？", "b_pw": "ui, vurati azua.", "b_zh": "是/對，那是地瓜。"}, {"id": 199, "page": 34, "section": "句型篇國中", "a_pw": "a veljevelj azua?", "a_zh": "那是香蕉嗎？", "b_pw": "ini, vuday azua.", "b_zh": "不，那是玉米。"}, {"id": 200, "page": 34, "section": "句型篇國中", "a_pw": "a qacengecengel a su ngiav?", "a_zh": "你的貓是黑色的嗎？", "b_pw": "ui, qacengecengel a ’u ngiav.", "b_zh": "是/對，我的貓是黑色的。"}, {"id": 201, "page": 34, "section": "句型篇國中", "a_pw": "a qudjidjilj a itung nimadju?", "a_zh": "她的衣服是紅色的嗎？", "b_pw": "ini, vuqavuqalj a itung nimadju.", "b_zh": "不，她的衣服是白色的。"}, {"id": 202, "page": 35, "section": "句型篇國中", "a_pw": "a qacaqaca ti tjama?", "a_zh": "你爸爸很高嗎？", "b_pw": "ui, namicaucauan a ’u ’ama.", "b_zh": "對，我爸爸很高大"}, {"id": 203, "page": 35, "section": "句型篇國中", "a_pw": "qacaqaca ti tjaina?", "a_zh": "你媽媽很高嗎？", "b_pw": "ini, kedrikedri a ’u ’ina.", "b_zh": "不，我媽媽很矮。"}, {"id": 204, "page": 35, "section": "句型篇國中", "a_pw": "caljeqiljeqil azua timadju?", "a_zh": "那個人很勤勞嗎？", "b_pw": "ui, tjambi aravac. /ui, caljeqi aravac.", "b_zh": "是/對，他很勤勞。"}, {"id": 205, "page": 35, "section": "句型篇國中", "a_pw": "a tjambibi azua timadju?", "a_zh": "那個人很勤勞嗎？", "b_pw": "ini, mavulaqut timadju. /vuljaqulaqut timadju.", "b_zh": "不，他很懶惰。"}, {"id": 206, "page": 35, "section": "句型篇國中", "a_pw": "izua macitilj a su siruvetje’ a vavayan a tjaljalja’ tjanusun aya’en?", "a_zh": "你不是有一個妹妹嗎？", "b_pw": "ini, madrusa a ’u siruvetje’ a vavayan a tjaljalja’ tjanua’en.", "b_zh": "不，我有二個妹妹。"}, {"id": 207, "page": 35, "section": "句型篇國中", "a_pw": "tjaljiqacaqaca azua umaq?", "a_zh": "那間房子很大嗎？", "b_pw": "ui, tjaljiqacaqaca azua umaq.", "b_zh": "是/對，那間房子很大。"}, {"id": 208, "page": 36, "section": "句型篇國中", "a_pw": "a tjaljiqacaqaca azua umaq?", "a_zh": "那間房子很大嗎？", "b_pw": "ini, tjaljikedrikedri azua umaq.", "b_zh": "不，那間房子很小。"}, {"id": 209, "page": 36, "section": "句型篇國中", "a_pw": "djemedjedjedje sun a pacun ta tinse?", "a_zh": "你天天看電視嗎？", "b_pw": "ini, djemedje a’en a ’itulu ta laqulj.", "b_zh": "不，我天天讀書。"}, {"id": 210, "page": 36, "section": "句型篇國中", "a_pw": "nataqed a su kaka/’a’a a vavayan?", "a_zh": "你妹妹在睡覺嗎？", "b_pw": "ui, nataqed timadju.", "b_zh": "是/對，她在睡覺。"}, {"id": 211, "page": 36, "section": "句型篇國中", "a_pw": "qemudjaqudjalj anga, ui?", "a_zh": "下雨了，是嗎？", "b_pw": "ui, qemudjaqudjalj anga.", "b_zh": "是/對，正在下雨。"}, {"id": 212, "page": 36, "section": "句型篇國中", "a_pw": "qemudjaqudjalj anan?", "a_zh": "在下雨嗎？", "b_pw": "ini anga, tjevuta anga a qadav.", "b_zh": "不了，太陽出來了！"}, {"id": 213, "page": 36, "section": "句型篇國中", "a_pw": "tjenglay sun a ’itulu ta laqulj?", "a_zh": "你喜歡讀書嗎？", "b_pw": "ui, tjenglay a’en aravac a ’itulu ta laqulj.", "b_zh": "是/對，我很喜歡讀書。"}, {"id": 214, "page": 37, "section": "句型篇國中", "a_pw": "saigu a za mare’a ’a’edrian a semenay?", "a_zh": "那些孩子會唱歌嗎？", "b_pw": "ui, saigu aravac a semenay tiamadju.", "b_zh": "會/對，他們很會唱歌。"}, {"id": 215, "page": 37, "section": "句型篇國中", "a_pw": "a saigu sun a venataq?", "a_zh": "你會洗衣服嗎？", "b_pw": "ui, macaqu a’en a venataq.", "b_zh": "會/對，我會洗衣服。"}, {"id": 216, "page": 37, "section": "句型篇國中", "a_pw": "a vaivai’ mun a semagakku a ’ivangavang?", "a_zh": "你們正要去學校玩耍嗎？", "b_pw": "ui, vaivai’ amen a semagakku a ’ivangavang.", "b_zh": "是/對，我們正要去學校玩耍。"}, {"id": 217, "page": 37, "section": "句型篇國中", "a_pw": "mapida a su siruvetje’?", "a_zh": "你有幾個兄弟姊妹？", "b_pw": "izua macidilj a tjavulung tjanua’en a uqaljay ta ’u siruvetje’, sa macidilj a tjaljalja’ tjanua’en.", "b_zh": "我有一個哥哥和一個弟弟。"}, {"id": 218, "page": 37, "section": "句型篇國中", "a_pw": "a djemedjedjedje a pacun ta iga tiamadju?", "a_zh": "他們天天看電視嗎？", "b_pw": "ui, djemedjedjedje a pacun ta iga tiamadju.", "b_zh": "是/對，他們天天看電視。"}, {"id": 219, "page": 38, "section": "句型篇高中", "a_pw": "a masulem anga?", "a_zh": "天黑了嗎？", "b_pw": "ui, maledep anga a qadav.", "b_zh": "是/對，太陽下山了！"}, {"id": 220, "page": 38, "section": "句型篇高中", "a_pw": "a uzai anga vali?", "a_zh": "颱風來了嗎？", "b_pw": "ui, paljeqaca anga ravac a qudjalj.", "b_zh": "是/對，今天雨下得很大。"}, {"id": 221, "page": 38, "section": "句型篇高中", "a_pw": "a rutjalupung timadju?", "a_zh": "她常常戴帽子嗎？", "b_pw": "ui, rutjalupulupung timadju.", "b_zh": "是/對，她常常戴帽子。"}, {"id": 222, "page": 38, "section": "句型篇高中", "a_pw": "a djemedjetdjedje mun a mamaza a ’aiv?", "a_zh": "你們天天來這裡吃晚餐嗎？", "b_pw": "ui, mamazamaza men sa’amaya a ’aiv?", "b_zh": "是/對，我們經常來這裡吃晚餐。"}, {"id": 223, "page": 38, "section": "句型篇高中", "a_pw": "a macaqu sun a venataq?", "a_zh": "你會洗衣服嗎？", "b_pw": "ui, saigu a’en a venataq.", "b_zh": "會/對，我會洗衣服。"}, {"id": 224, "page": 38, "section": "句型篇高中", "a_pw": "tjengelay a zemuga azua alja’?", "a_zh": "那個孩子喜歡畫圖嗎？", "b_pw": "ini, ini a tjengelay timadju a zemuga.", "b_zh": "不，他不喜歡畫圖。"}, {"id": 225, "page": 39, "section": "句型篇高中", "a_pw": "saigu a semenay azua alja’?", "a_zh": "那個孩子會唱歌嗎？", "b_pw": "ini, ini a saigu a semenay timadju.", "b_zh": "不，他不會唱歌。"}, {"id": 226, "page": 39, "section": "句型篇高中", "a_pw": "maqati a’en a vai’ a casav nu masu’incengelj a ’ivangavang?", "a_zh": "下午我可以出去玩嗎？(請求同意)", "b_pw": "ini a maqati, maya a vai’ a casav a ’ivangavang!", "b_zh": "不，你不可以出去玩！"}, {"id": 227, "page": 39, "section": "句型篇高中", "a_pw": "paqenetju a tjumaq a ’aiv!", "a_zh": "請記得回家吃晚餐！", "b_pw": "ui, ’emeljang.", "b_zh": "好，知道"}, {"id": 228, "page": 39, "section": "句型篇高中", "a_pw": "nu meljay, maqati a’en a casav a ’ivangavang?", "a_zh": "如果雨停了，我可以出去玩嗎？", "b_pw": "nu meljay, maqati anga sun a casav a ’ivangavang?", "b_zh": "如果雨停了，你可以出去玩。"}, {"id": 229, "page": 39, "section": "句型篇高中", "a_pw": "natjemalupung ti ’ina ta casav?", "a_zh": "媽媽出去的時候，她戴著帽子嗎？", "b_pw": "ui, natjemalupung ti ’ina sa casav.", "b_zh": "是/對，媽媽出去的時候，她戴著帽子。"}, {"id": 230, "page": 39, "section": "句型篇高中", "a_pw": "na’emacu ta kausua ti ’ama sa casav?", "a_zh": "爸爸出去的時候，他帶著雨傘嗎？", "b_pw": "ini, ini a na’emacu ta kausua ti ’ama sa casav.", "b_zh": "不，爸爸出去的時候，他沒有帶著雨傘。"}, {"id": 231, "page": 40, "section": "句型篇高中", "a_pw": "a ’emeljang mun turi mangtjez nutiav ti ’acumusu?", "a_zh": "你們知道祖母明天要來嗎？", "b_pw": "ui, ’emeljang a men turi mangtjez ti vuvu nutiav.", "b_zh": "是，我們知道祖母明天要來。"}, {"id": 232, "page": 40, "section": "句型篇高中", "a_pw": "anema cu?", "a_zh": "這是什麼？", "b_pw": "kiav aicu.", "b_zh": "這是青蛙。"}, {"id": 233, "page": 40, "section": "句型篇高中", "a_pw": "anema azua?", "a_zh": "那是什麼？", "b_pw": "tjalupung azua.", "b_zh": "那是帽子。"}, {"id": 234, "page": 40, "section": "句型篇高中", "a_pw": "pida laqulj nuazua alja’?", "a_zh": "那個小孩有幾本書？", "b_pw": "izua drusa laqulj nimadju.", "b_zh": "她有二本書。"}, {"id": 235, "page": 40, "section": "句型篇高中", "a_pw": "pida laqulj nuazua alja’?", "a_zh": "那個小孩有幾本書？", "b_pw": "liav a laqulj nimadju.", "b_zh": "她有很多本書。"}, {"id": 236, "page": 40, "section": "句型篇高中", "a_pw": "nanzi anga tucu?", "a_zh": "現在是幾點鐘？", "b_pw": "sicizi anga tucu.", "b_zh": "現在是四點鐘。"}, {"id": 237, "page": 41, "section": "句型篇高中", "a_pw": "izainu a kadray nimadju?", "a_zh": "他/她的揹簍在哪裡？", "b_pw": "zai a kadray nimadju", "b_zh": "他/她的揹簍在那裡。"}, {"id": 238, "page": 41, "section": "句型篇高中", "a_pw": "a ni a’en cu a paisu?", "a_zh": "這是我的錢嗎？", "b_pw": "ui, nisun cu a paisu.", "b_zh": "是的，這是你的錢。"}, {"id": 239, "page": 41, "section": "句型篇高中", "a_pw": "a nisun azua mare’a hana?", "a_zh": "那些是你的花嗎？", "b_pw": "ini, ini ni a’en azua hana.", "b_zh": "不是，那些不是我的花。"}, {"id": 240, "page": 41, "section": "句型篇高中", "a_pw": "ma’uda sun?", "a_zh": "你怎麼了？", "b_pw": "saqetjuqetju aza ’u macu.", "b_zh": "我的眼睛很痛。"}, {"id": 241, "page": 41, "section": "句型篇高中", "a_pw": "sadjeludjelung cu a cukui?", "a_zh": "這張桌子很重嗎？", "b_pw": "ui, sadjelung aravac cu a cukui", "b_zh": "是/對，這張桌子很重。"}, {"id": 242, "page": 41, "section": "句型篇高中", "a_pw": "sadjeludjelung azua qiladjan?", "a_zh": "那張椅子很重嗎？", "b_pw": "ini, saceqaceqalj azua qiladjan.", "b_zh": "不，那張椅子很輕。"}, {"id": 243, "page": 42, "section": "句型篇高中", "a_pw": "tjengelay azua mare’a ’a’edrian a iyugi?", "a_zh": "那些孩子喜歡跳舞嗎？", "b_pw": "ini, tjengelay tiamadju a pacun ta iga.", "b_zh": "不，他們喜歡看電視。"}, {"id": 244, "page": 42, "section": "句型篇高中", "a_pw": "tjengelay azua mare’a ’a’edrian a ’ivangavang?", "a_zh": "那些孩子喜歡玩耍嗎？", "b_pw": "ini, tjengelay tiamadju a mapu/tjaljamtjam.", "b_zh": "不，他們喜歡吃東西。"}, {"id": 245, "page": 43, "section": "親子族語", "a_pw": "gacalju pai, ne’a anga su zikang a ’enama.", "a_zh": "快點起來，不然，你沒時間吃早餐唷！", "b_pw": "gata ini anan a’en a ’asudaqedan.", "b_zh": "可是我還沒睡飽"}, {"id": 246, "page": 43, "section": "親子族語", "a_pw": "ipang, izua su’initulu tucu a qadav?", "a_zh": "ipang，你今天有學到什麼嗎？", "b_pw": "izua, liav a ’u’initulu tucu", "b_zh": "有啊，我今天學到很多"}, {"id": 247, "page": 43, "section": "親子族語", "a_pw": "’ani anga!", "a_zh": "吃飯了！", "b_pw": "ui, zanganga a’en!", "b_zh": "好，馬上。"}, {"id": 248, "page": 43, "section": "親子族語", "a_pw": "izua su vaveci’an tucu?", "a_zh": "今天你有作業要寫嗎？", "b_pw": "izua ’u zazugain tucu.", "b_zh": "有，我有畫畫作業。"}, {"id": 249, "page": 43, "section": "親子族語", "a_pw": "mainu itjen nutiav?", "a_zh": "我們明天要去哪裡呢？", "b_pw": "sa vai’ a’en a mata nanguanguaq a ’a’ivangavangan.", "b_zh": "我想去很好玩的地方。"}, {"id": 250, "page": 43, "section": "親子族語", "a_pw": "tauki, pida anga cu a penuljat?", "a_zh": "老闆，這樣總共多少錢？", "b_pw": "taiday sa enem anga puluq a penuljat.", "b_zh": "這樣是160元。"}];

    // 2. Core Vocabularies
    window.PAIWAN_VOCAB_LIST = [{"word": "cukui", "meaning": "桌子", "example": "cukui cu. (這是桌子。)"}, {"word": "laqulj", "meaning": "書本", "example": "pida su laqulj? (你有幾本書？)"}, {"word": "sinsi", "meaning": "老師", "example": "ni sinsi aza qudjidjilj a laqulj. (那本紅色的書是老師的。)"}, {"word": "qudjalj", "meaning": "雨", "example": "paljeqaca anga ravac a qudjalj. (今天雨下得很大。)"}, {"word": "qiljas", "meaning": "月亮", "example": "ne’a za qiljas sa ne’a za qerepus. (沒月也無雲。)"}, {"word": "vitjuqan", "meaning": "星星", "example": "mapacucun a vitjuqan. (看得到星星。)"}, {"word": "qadav", "meaning": "太陽 / 日子 / 天氣", "example": "mezangal aravac a qadav. (太陽好大。)"}, {"word": "’inpic", "meaning": "筆", "example": "ini a’en a paqenetj anga a ’emacu tua ’u ’inpic. (我忘了帶筆。)"}, {"word": "siquliqulip", "meaning": "橡皮擦", "example": "pai alapu a nu siquliqulip. (來把你們的橡皮擦取走。)"}, {"word": "vatu", "meaning": "狗", "example": "ita a vatu nimadju. (他有一隻狗。)"}, {"word": "maca", "meaning": "眼睛", "example": "saqetju a za ’u maca. (我的眼睛痛。)"}, {"word": "qulu", "meaning": "頭", "example": "saqetju a ’u qulu. (我的頭很痛。)"}, {"word": "tjalupung", "meaning": "帽子", "example": "rutjalupulupung timadju. (她常常戴帽子。)"}, {"word": "venataq", "meaning": "洗衣服", "example": "saigu a’en a venataq. (我會洗衣服。)"}, {"word": "zemuga", "meaning": "畫圖", "example": "tjengelay a zemuga azua alja’? (那個孩子喜歡畫圖嗎？)"}, {"word": "djalan", "meaning": "道路 / 馬路", "example": "tjevetjeveng a ’adjalanan. (你看馬路是濕的。)"}, {"word": "vali", "meaning": "風 / 颱風", "example": "a uzai anga vali? (颱風來了嗎？)"}, {"word": "tace’eljan", "meaning": "家人 / 家庭", "example": "masepatj amen a tace’eljan. (我們家有4個人。)"}, {"word": "ngadaan", "meaning": "名字", "example": "tima ngadaan ni tjama? (你爸爸叫什麼名字？)"}, {"word": "sikausua", "meaning": "雨傘", "example": "ini a’en a namasikausua. (我沒有帶雨傘。)"}, {"word": "enama", "meaning": "早餐", "example": "ne’a anga su zikang a ’enama. (你沒時間吃早餐唷！)"}, {"word": "’aiv", "meaning": "晚餐", "example": "mamaza a ’aiv? (來這裡吃晚餐？)"}, {"word": "zikang", "meaning": "時間 / 鐘點", "example": "sicizikang anga. (現在是四點鐘。)"}, {"word": "sepatj", "meaning": "數字「四」", "example": "masepatj amen a tace’eljan. (我們家有4個人。)"}, {"word": "tjelu", "meaning": "數字「三」", "example": "izua a tjelu a laqulj. (有三本書放在桌上。)"}, {"word": "drusa", "meaning": "數字「二」", "example": "drusa a ’u laqulj. (我有二本書。)"}, {"word": "ita", "meaning": "數字「一」", "example": "ita a vatu nimadju. (他有一隻狗。)"}, {"word": "taiday", "meaning": "數字「一百」", "example": "taiday sa enem anga puluq. (一百六十元。)"}, {"word": "pulingalingav", "meaning": "聽得懂 / 明白", "example": "pulingalingav sun tua ’u sinitulu? (你聽得懂我教的嗎？)"}, {"word": "sengesengan", "meaning": "工作", "example": "anema sengsengan ni tjaina? (你媽媽做什麼工作？)"}];
    window.PAIWAN_DISTRACTOR_VOCABS = ["衣服", "褲子", "水壺", "書包", "學校", "學生", "山豬", "百步蛇", "山林", "河流", "中午", "下午", "晚上", "走路", "唱歌", "跳舞", "高興", "生氣", "數字五", "數字六", "飛機", "腳踏車", "窗戶", "大門"];

    // Utility: Shuffle Array
    function shuffle(arr) {
        var a = arr.slice();
        for (var i = a.length - 1; i > 0; i--) {
            var j = Math.floor(Math.random() * (i + 1));
            var tmp = a[i];
            a[i] = a[j];
            a[j] = tmp;
        }
        return a;
    }

    /**
     * 動態生成本局題庫（每次開局隨機全新抽題，保證題目不同）
     * 100% 依據《25中排灣語_句型練習.pdf》出題
     * - 語意理解 130 題 (排灣語 -> 中文)
     * - 族語表達 90 題 (中文 -> 排灣語)
     * - 情境對話 50 題 (純排灣語問答，零中文洩題)
     * - 核心詞彙 30 題 (單字與例句)
     */
    window.generatePaiwanQuestionBank = function() {
        var raw = window.PAIWAN_RAW_DATASET || [];
        var vocab = window.PAIWAN_VOCAB_LIST || [];
        var distVocab = window.PAIWAN_DISTRACTOR_VOCABS || [];

        var allZh = [];
        var allPw = [];
        for (var i = 0; i < raw.length; i++) {
            if (raw[i].a_zh) allZh.push(raw[i].a_zh);
            if (raw[i].b_zh) allZh.push(raw[i].b_zh);
            if (raw[i].a_pw) allPw.push(raw[i].a_pw);
            if (raw[i].b_pw) allPw.push(raw[i].b_pw);
        }

        var uniqueZh = Array.from(new Set(allZh));
        var uniquePw = Array.from(new Set(allPw));

        var questions = [];
        var qId = 1;

        // 1. 語意理解 (130 題): 排灣語句 -> 中文意思
        var pool1 = shuffle(raw);
        var count1 = Math.min(130, pool1.length);
        for (var i = 0; i < count1; i++) {
            var d = pool1[i];
            var useB = (i % 2 === 1 && d.b_pw && d.b_zh);
            var pw = useB ? d.b_pw : d.a_pw;
            var zh = useB ? d.b_zh : d.a_zh;

            var dList = uniqueZh.filter(function(s) {
                return s !== zh && Math.abs(s.length - zh.length) < 25;
            });
            if (dList.length < 3) {
                dList = uniqueZh.filter(function(s) { return s !== zh; });
            }
            dList = shuffle(dList).slice(0, 3);

            var opts = shuffle([zh].concat(dList));
            var ans = opts.indexOf(zh);

            questions.push({
                id: qId++,
                subject: "中排灣語",
                category: d.section,
                type: "語意理解",
                question: "【中排灣語 語意理解】\n請問下列排灣語句子的中文意思是什麼？\n「" + pw + "」",
                options: opts,
                answer: ans,
                explanation: "正確中文為：「" + zh + "」。\n選自《25中排灣語_句型練習.pdf》第 " + d.page + " 頁【" + d.section + "】。"
            });
        }

        // 2. 族語表達 (90 題): 中文句 -> 排灣語表達
        var pool2 = shuffle(raw);
        var count2 = Math.min(90, pool2.length);
        for (var i = 0; i < count2; i++) {
            var d = pool2[i];
            var useB = (i % 2 === 0 && d.b_pw && d.b_zh);
            var pw = useB ? d.b_pw : d.a_pw;
            var zh = useB ? d.b_zh : d.a_zh;

            var dList = uniquePw.filter(function(s) {
                return s !== pw && Math.abs(s.length - pw.length) < 30;
            });
            if (dList.length < 3) {
                dList = uniquePw.filter(function(s) { return s !== pw; });
            }
            dList = shuffle(dList).slice(0, 3);

            var opts = shuffle([pw].concat(dList));
            var ans = opts.indexOf(pw);

            questions.push({
                id: qId++,
                subject: "中排灣語",
                category: d.section,
                type: "族語表達",
                question: "【中排灣語 族語表達】\n若要表達中文「" + zh + "」，正確的中排灣語說法是：",
                options: opts,
                answer: ans,
                explanation: "正確中排灣語為：「" + pw + "」。\n選自《25中排灣語_句型練習.pdf》第 " + d.page + " 頁【" + d.section + "】。"
            });
        }

        // 3. 情境對話 (50 題): 純排灣語對話（零中文洩題）
        var dialoguePool = raw.filter(function(d) { return d.a_pw && d.b_pw; });
        var pool3 = shuffle(dialoguePool);
        var count3 = Math.min(50, pool3.length);
        for (var i = 0; i < count3; i++) {
            var d = pool3[i];
            var correctB = d.b_pw;
            var correctBZh = d.b_zh;

            var otherBs = dialoguePool.filter(function(o) {
                return o.id !== d.id && o.b_pw !== correctB;
            }).map(function(o) { return o.b_pw; });

            var dList = shuffle(otherBs).slice(0, 3);
            var opts = shuffle([correctB].concat(dList));
            var ans = opts.indexOf(correctB);

            questions.push({
                id: qId++,
                subject: "中排灣語",
                category: d.section,
                type: "情境對話",
                question: "【中排灣語 情境對話】\n說話者 A 說：\n「" + d.a_pw + "」\n請問說話者 B 最適當的回應是？",
                options: opts,
                answer: ans,
                explanation: "【對話解析】\n說話者 A 說：「" + d.a_pw + "」(" + d.a_zh + ")\n正確回應 B 說：「" + correctB + "」(" + correctBZh + ")\n選自《25中排灣語_句型練習.pdf》第 " + d.page + " 頁【" + d.section + "】。"
            });
        }

        // 4. 核心詞彙 (30 題): 單字與語義
        var pool4 = shuffle(vocab);
        var count4 = Math.min(30, pool4.length);
        for (var i = 0; i < count4; i++) {
            var v = pool4[i];
            var wrongPool = vocab.filter(function(item) {
                return item.meaning !== v.meaning;
            }).map(function(item) { return item.meaning; }).concat(distVocab);

            var dList = shuffle(wrongPool).slice(0, 3);
            var opts = shuffle([v.meaning].concat(dList));
            var ans = opts.indexOf(v.meaning);

            questions.push({
                id: qId++,
                subject: "中排灣語",
                category: "核心詞彙",
                type: "核心詞彙",
                question: "【中排灣語 核心詞彙】\n在句型對話練習中，排灣語單字「" + v.word + "」是指下列何者？",
                options: opts,
                answer: ans,
                explanation: "「" + v.word + "」的意思是「" + v.meaning + "」。\n例句：" + v.example
            });
        }

        return questions;
    };

    // 初始載入時立即動態生成一組題目
    window.QUESTION_BANK = window.generatePaiwanQuestionBank();
})();
